import{_ as s,o as n,c as e,ag as t}from"./chunks/framework.DUTPmUpA.js";const p="/_assets/XqzWA3I.Dj-5XRWy.jpg",u=JSON.parse('{"title":"Заскриптованный спаун магазина","description":"","frontmatter":{"title":"Заскриптованный спаун магазина","author":"snippet","steamId":"76561198017441460","date":"29.04.2015"},"headers":[],"relativePath":"scripting/scripted-shop-spawning.md","filePath":"scripting/scripted-shop-spawning.md"}'),i={name:"scripting/scripted-shop-spawning.md"};function r(o,a,l,c,d,h){return n(),e("div",null,[...a[0]||(a[0]=[t('<p>иптованный спаун магазина</p><p>Часто задаваемая функция — динамическое создание магазинов. Оказывается, это на самом деле довольно легко! Вот что делать.</p><h2 id="шаг-1" tabindex="-1">Шаг 1. <a class="header-anchor" href="#шаг-1" aria-label="Permalink to &quot;Шаг 1.&quot;">​</a></h2><p>Вам необходимо создать триггерную зону для вашего магазина в Hammer. Используйте инструмент «Блок» (<strong>ctrl+b</strong>), чтобы нарисовать нужную область срабатывания магазина. Вы можете изменить форму с помощью инструмента «Блок» на любую, которая вам нужна.</p><p>Нарисуйте местность где-нибудь за пределами карты. Вы не хотите, чтобы игроки случайно наткнулись на него.</p><h2 id="шаг-2" tabindex="-1">Шаг 2. <a class="header-anchor" href="#шаг-2" aria-label="Permalink to &quot;Шаг 2.&quot;">​</a></h2><p>Превратите блок в объект, выделив его и нажав <strong>ctrl+t</strong>. Измените класс сущности на триггер_шоп и дайте ему имя. Также отфильтруйте материалы и найдите материал триггера, перетащите его на блок. Наконец, установите тип магазина внизу. Теперь это должно выглядеть так: <img src="'+p+`" alt="ShopInHammer" title="ShopInHammer">. Когда это будет сделано, восстановите карту.</p><h2 id="шаг-3" tabindex="-1">Шаг 3. <a class="header-anchor" href="#шаг-3" aria-label="Permalink to &quot;Шаг 3.&quot;">​</a></h2><p>Теперь просто добавьте следующий код, чтобы создать магазин в нужном вам месте! Я добавил это в OnConstructionCompleted в помощнике по сборке.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>local shopEnt = Entities:FindByName(nil, &quot;my_new_shop&quot;) -- entity name in hammer</span></span>
<span class="line"><span>local newshop = SpawnEntityFromTableSynchronous(&#39;trigger_shop&#39;, {origin = unit:GetAbsOrigin(), shoptype = 1, model=shopEnt:GetModelName()}) -- shoptype is 0 for a &quot;home&quot; shop, 1 for a side shop and 2 for a secret shop</span></span>
<span class="line"><span>\`\`\`Пример:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;StaticVideo path=&quot;/videos/DimwittedGlisteningAmericanmarten.mp4&quot; /&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div>`,10)])])}const b=s(i,[["render",r]]);export{u as __pageData,b as default};
